"""Build the Y9 Electricity hub, two lessons, four experiment pages and revision wrappers."""
import sys
sys.dont_write_bytecode=True
import json,subprocess
from pathlib import Path
from electricity_lessons import STATIC,CIRCUITS
ROOT=Path(__file__).resolve().parent.parent
DEST=ROOT/'activities/y9/science/electricity';DEST.mkdir(parents=True,exist_ok=True)
art=json.loads(subprocess.check_output(['node','--input-type=module','-e',"import{cover,atomArt,readingFigures}from './assets/y9-electricity/art.mjs'; console.log(JSON.stringify({unit:cover(),static:cover('static'),circuit:cover('circuit'),atom:atomArt(),...readingFigures()}));"],cwd=ROOT,text=True))
for key in art:(DEST/'images'/f'{key}.svg').write_text(art[key])
NAMES={'pizza':'The Pizza Circuit','resistance':'The Resistance Run','ohms-law':'Build an Ohm’s law circuit','wire-resistance':'Inside a resistance wire'}
def shell(title,body,depth=4,kind=None):
 p='../'*depth;unit=p+'activities/y9/science/electricity/'
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#e5eef7"><title>{title} | Y9 Electricity | Learning Lab</title><meta name="description" content="Beginner-friendly electricity lessons, direct-interaction experiments, illustrated charge and circuit models, graphs and revision."><link rel="icon" href="{p}assets/brand/learning-lab-logo.png"><link rel="stylesheet" href="{p}assets/y9-electricity/electricity.css?v=pizza-film-1">{f'<script type="module" src="{p}assets/y9-electricity/lab.js?v=pizza-film-1"></script>' if kind else ''}</head><body{f' data-lab="{kind}"' if kind else ''}><a class="skip" href="#main">Skip to lesson</a><header class="site-header"><a class="brand" href="{p}index.html"><img src="{p}assets/brand/learning-lab-logo.png" alt="" width="43" height="43">learning<span>lab</span></a><nav aria-label="Main navigation"><a href="{p}index.html#/years/y9/science">Y9 Science</a><a href="{unit}">Electricity</a><a href="{unit}static/">Static electricity</a><a href="{unit}circuits/">Circuits</a></nav></header><main id="main"><nav class="crumbs" aria-label="Breadcrumb"><a href="{p}index.html">Home</a> › <a href="{p}index.html#/years/y9/science">Y9 Science</a> › <a href="{unit}">Electricity</a> › {title}</nav>{body}<noscript><p>The lesson text is available without JavaScript. Enable JavaScript to operate the experiments.</p></noscript></main><footer class="site-footer"><span>Learning Lab · Y9 Science · Electricity</span><a href="{unit}">Explore the two parts of Electricity →</a></footer></body></html>'''
def head(n,tag,title,desc=''):return f'<div class="section-head"><span class="section-number">{n:02}</span><div><span class="kicker">{tag}</span><h2>{title}</h2>{"<p>"+desc+"</p>" if desc else ""}</div></div>'
def reading(rows):
 cards=[]
 figures={0:('symbols','Standard symbols for a cell, lamp, resistor and open switch'),1:('current','Selected negative charge packets passing a counting line in a wire'),2:('voltage','A cell supplies energy per charge; a component transfers it'),5:('geometry','A round wire labelled with length L and diameter d'),6:('paths','One series path compared with two resistive parallel branches')}
 for i,(h,*paragraphs) in enumerate(rows):
  figure=('atom','Protons, neutrons and electrons with their charges') if rows is STATIC and i==0 else figures.get(i) if rows is CIRCUITS else None
  image=f'<img class="reading-art" src="../images/{figure[0]}.svg" width="840" height="300" alt="{figure[1]}">' if figure else ''
  paras=''.join('<p'+(' class="memory"' if 'Remember:' in t else ' class="word-key"' if j==3 else '')+'>'+t+'</p>' for j,t in enumerate(paragraphs))
  cards.append(f'<article class="lesson"><span class="kicker">IDEA {i+1:02}</span><h3>{h}</h3>{image}{paras}</article>')
 return '<div class="reading-grid">'+''.join(cards)+'</div>'
def revision(n,href,title='Electricity',count=60):return f'<section class="revision-invite" id="revision-invitation"><div><span class="kicker">{n:02} / INDEPENDENT REVISION</span><h2>Ready to test your understanding?</h2><p>{count} explained multiple-choice questions on {title.lower()}. Choose question areas and levels in the dropdowns. Practice gives guidance; Test yourself reviews your independent answers.</p></div><a class="button primary" href="{href}">Open revision simulator →</a></section>'
sources='''<details class="sources"><summary>About these models and your lesson sources</summary><p>Lessons follow the teacher-supplied <cite>Static Electricity and charge Presentation</cite> (26 slides) and <cite>CircuitsPresentation</cite> (54 slides). The original pizza and obstacle illustrations are retained unchanged from those presentations. The Pizza Circuit and Resistance Run also use edited background and character layers to animate those pictures. Explanations and interactive artwork are written for this platform. Every needed instruction is on the page.</p><p>Models slow and enlarge charge motion. Real electrons have fast random motion and a small net drift; an electrical signal propagates much faster than individual electrons drift. Energy transfer involves fields. The pizza and playground models are analogies, not microscopic mechanisms. Ideal circuit meters, a regulated supply and controlled resistor temperatures omit experimental uncertainty.</p></details>'''
def cards(prefix=''):
 return '<div class="cards">'+''.join(f'<article class="card"><img src="{prefix}images/{image}" width="770" height="440" alt="{alt}"><div><span class="kicker">{tag}</span><h3>{NAMES[k]}</h3><p>{desc}</p><a class="button primary" href="{prefix}simulators/{k}.html">Open this investigation →</a></div></article>' for k,image,alt,tag,desc in [
 ('pizza','pizza-circuit.png','The teacher’s pizza delivery loop with shop, couriers and party','CHARGE AND ENERGY','Follow highlighted couriers around your pizza circuit. Change energy per charge and resistance; watch current respond everywhere.'),
 ('resistance','resistance-obstacles.png','The teacher’s obstacle-course analogy for resistance','RESISTANCE WITHOUT LOST CHARGE','Watch charge markers complete the obstacle loop. Compare resistance, current and energy transfer; the same charge continues.'),
 ('ohms-law','circuit.svg','Illustration of a low-voltage supply and resistor circuit','BUILD · MEASURE · GRAPH','Connect an ammeter and voltmeter on the apparatus, close the switch and collect I–V readings. Compare single, series and parallel networks.'),
 ('wire-resistance','circuit.svg','A resistance experiment with electrical instruments','CHANGE ONE FACTOR','Inspect an enlarged wire. Investigate length, diameter, material and temperature with a fixed measuring current and live resistance graph.')])+'</div>'
body=f'''<section class="hero"><div><span class="kicker">YEAR 9 SCIENCE · ELECTRICITY</span><h1>One charge.<br>Two stories.</h1><p>A balloon clings to a wall. A circuit lights up. Begin with the tiny charged particles behind both, then investigate how a complete path lets energy transfer.</p><div class="row"><a class="button primary" href="static/">Start with static electricity →</a><a class="button" href="circuits/">Explore circuits →</a></div></div><img src="images/unit.svg" alt="A colourful low-voltage circuit with charge markers" width="840" height="440"></section><section>{head(1,'YOUR LEARNING PATH','Electricity, in two parts.','New to the topic? Follow Part 1 before Part 2. Each lesson explains vocabulary, shows examples and guides you through experiments.')}<div class="cards"><article class="part-card"><span class="section-number">01</span><h2>Static electricity<br>and charge</h2><p>Atoms → electron transfer → attraction and repulsion → conductors and insulators → earthing → useful and unwanted discharges.</p><p><strong>Try it:</strong> rub a virtual balloon, compare charged objects and attach an earth lead. Watch electrons move and check both charge totals.</p><a class="button primary" href="static/">Open Part 1 →</a></article><article class="part-card"><span class="section-number">02</span><h2>Electric<br>circuits</h2><p>A complete loop → current → potential difference → resistance → Ohm’s law → series and parallel paths → power.</p><p><strong>Try it:</strong> follow the pizza model, explore the resistance course, connect meters and investigate a wire with graphs.</p><a class="button primary" href="circuits/">Open Part 2 →</a></article></div></section><section>{head(2,'MEET THE EXPERIMENTS','Where do we meet electricity?','Open an illustrated model, then test its ideas with instruments. The controls and observations share the experiment workspace.')}{cards()}</section>{sources}<section class="revision-invite" id="revision-invitation"><div><span class="kicker">03 / INDEPENDENT REVISION</span><h2>Ready to test your understanding?</h2><p>Two separate revision simulators: 60 questions on static electricity and 60 on circuits. Select areas and question levels, practise with explanations or take Test yourself.</p></div><div class="row"><a class="button" href="static/revision.html">Static electricity revision →</a><a class="button primary" href="circuits/revision.html">Circuits revision →</a></div></section>'''
(DEST/'index.html').write_text(shell('Electricity',body))

def slider(id,label,min,max,step,value,unit='',wide=False):return f'<label class="{"wide" if wide else ""}"><span>{label}<output id="{id}-value" for="{id}">{value} {unit}</output></span><input type="range" id="{id}" min="{min}" max="{max}" step="{step}" value="{value}"></label>'
def check():return '''<section class="quick-check" id="check-understanding"><span class="kicker">CHECK YOUR UNDERSTANDING</span><h2>Explain what you observed.</h2><div id="local-question"></div><div class="row"><button id="check-answer" class="primary">Check my explanation</button><button id="next-check" hidden>Next question →</button></div><p id="check-feedback" class="status" role="status"></p></section>'''
def bench(kind,controls,instruction,side,records=False):
 return f'''<div class="bench" id="experiment-bench"><div class="bench-top"><span class="kicker">YOUR EXPERIMENT WORKSPACE</span><div class="row"><button id="pause-motion" aria-pressed="false">Pause motion</button><button id="reset-lab">Reset experiment</button></div></div><div class="instruction" id="lab-instruction">{instruction}</div><div class="lab-grid"><div class="instrument"><div class="scene" id="scene"></div><div class="readouts" id="readouts"></div><div class="controls">{controls}</div><p class="caption" id="scene-caption"></p></div><aside class="observations"><h2>{side}</h2><div id="observations"></div><div class="graph" id="graph"></div><div class="trace-legend" id="trace-legend"></div><p class="graph-caption" id="graph-caption"></p><div class="predict" id="prediction-box" {'hidden' if kind=='static' else ''}><label for="prediction">Predict the current after your next change</label><select id="prediction"><option value="rise">It will increase</option><option value="fall">It will decrease</option><option value="same">It will stay the same</option></select><button id="save-prediction">Save my prediction</button><p id="prediction-result" class="status" role="status"></p></div><p id="lab-feedback" class="status" role="status"></p><button id="help-step">Help me with this step</button></aside></div>{'<div class="local-records"><div class="row"><div><span class="kicker">YOUR EVIDENCE</span><h2>Record and compare your results.</h2></div><div class="row"><button id="record-result" class="primary">Record this reading</button><button id="clear-results">Clear readings</button></div></div><p>Keep your observations directly below the apparatus and graph. These experimental readings stay on this page; they are not teacher test records.</p><div class="table-scroll"><table><thead id="results-head"></thead><tbody id="results-body"></tbody></table></div><p id="record-feedback" class="status" role="status"></p></div>' if records else ''}<details class="model-explanation" id="model-explanation"><summary>Unpack the observations and model</summary><div id="deep-observations"></div></details><div class="model-limits" id="model-limits"></div></div>'''
staticcontrols='''<label class="wide">Choose an investigation<select id="static-mode"><option value="charging">1 · Transfer electrons: balloon and cloth</option><option value="forces">2 · Compare attraction and repulsion</option><option value="earthing">3 · Earth a charged metal sphere</option></select></label><div class="wide row" id="static-tools"></div>'''
for unit,title,rows,key in [('static','Static electricity and charge',STATIC,'static'),('circuits','Electric circuits',CIRCUITS,'circuit')]:
 folder=DEST/unit;folder.mkdir(exist_ok=True)
 body=f'''<section class="hero"><div><span class="kicker">Y9 ELECTRICITY · PART {'1' if unit=='static' else '2'}</span><h1>{'Invisible charge.<br>Visible effects.' if unit=='static' else 'Close the loop.<br>Follow the energy.'}</h1><p>{'Start from the atom. Learn why rubbing can change an object’s charge, why a neutral wall can attract a balloon, and how a conducting path can remove an imbalance.' if unit=='static' else 'Understand what flows and what transfers, then put your ideas to work with animated analogies, a circuit bench and measurements.'}</p><a class="button primary" href="#{'static-lab' if unit=='static' else 'examples'}">Explore the experiments ↓</a></div><img src="../images/{key}.svg" width="840" height="440" alt="{'A charged balloon and positive charge symbols' if unit=='static' else 'A low-voltage supply and resistor loop'}"></section><section id="learn-first">{head(1,'READ · PICTURE · EXPLAIN','Learn the ideas before you investigate.','Each card starts with a new idea, unpacks the vocabulary and connects it to an example.')}{reading(rows)}</section>'''
 if unit=='static':body+=f'''<section id="static-lab">{head(2,'PREDICT · INVESTIGATE · EXPLAIN','Make the invisible visible.','Choose an investigation, follow the highlighted instruction and act on the object inside the experiment.')}{bench('static',staticcontrols,'Select the balloon, then drag it across the cloth or click the cloth to rub it.','Compare your observations')}{check()}</section><section>{head(3,'CONNECT TO EVERYDAY LIFE','Small charges. Useful effects.')}<div class="connections"><article><h3>Clothes in a dryer</h3><p>Repeated contact and separation can transfer electrons. Dry insulating fabrics can keep a charge imbalance and attract other items.</p></article><article><h3>Printing a worksheet</h3><p>Controlled charged patterns attract toner to selected places. Electrical attraction helps form the image before toner is fixed to the paper.</p></article><article><h3>Industrial particle collection</h3><p>Charged particles can be drawn out of an exhaust stream towards collector plates. Removing particles differs from removing every gas pollutant.</p></article></div></section>'''
 else:body+=f'<section id="examples">{head(2,"MODEL · TEST · MEASURE","Where do we meet electricity?","Choose a separate investigation. Start with the two analogies, then use instruments to test the relationships.")}{cards("../")}</section><section>{head(3,"CONNECT TO EVERYDAY LIFE","One set of ideas, many applications.")}<div class="connections"><article><h3>A phone charger</h3><p>A regulated supply provides a potential difference. The connected device and its control electronics determine current; a voltage label alone is not a current reading.</p></article><article><h3>A toaster element</h3><p>Resistance supports energy transfer to heating. Nichrome has a much larger resistivity than copper, explaining why identical wire dimensions can behave differently.</p></article><article><h3>Household branches</h3><p>Parallel connections let appliances share a supply potential difference and operate on separate branches. Household installations involve further protective devices and mains hazards.</p></article></div></section>'
 body+=sources+revision(4,'revision.html',title)
 (folder/'index.html').write_text(shell(title,body,5,'static' if unit=='static' else None))
 # Reuse established revision engine and its readiness-gated Test yourself recording.
 template=(ROOT/'activities/y9/science/blood-vessels/revision.html').read_text().replace('../../../../','../../../../../').replace('blood-vessels',f'y9-electricity-{unit}').replace('Inside your blood vessels',title).replace('>Y7</a>','>Y9</a>').replace('>Maths</a>','>Science</a>')
 template=template.replace(f'#/years/y9/science/y9-electricity-{unit}', '#/years/y9/science/electricity')
 (folder/'revision.html').write_text(template)

configs={
'pizza':('Bring the picture to life: collect pizzas at the shop, deliver energy to the party, then follow the same couriers back.',slider('voltage','Supply potential difference',1,6,1,3,'V')+slider('resistance','Circuit resistance',1,6,1,3,'Ω')+'<div class="wide row"><button id="toggle-switch">Open the road switch</button></div>','Follow charge and energy',[
 'Raise voltage: each 1 C courier collects more pizza boxes, each representing 1 J of energy.','Raise resistance: speed humps grow and the road gets rougher, slowing all the couriers.','Follow a delivery and the empty return journey. The same charge continues; click the gate to stop the whole circuit.']),
'resistance':('Bring the picture to life: change voltage to energise the blue runners, or resistance to transform their obstacles.',slider('voltage','Supply potential difference',1,6,1,3,'V')+slider('resistance','Equivalent obstacle resistance',1,12,1,3,'Ω')+'<div class="wide row"><button id="toggle-switch">Open the circuit gate</button></div>','Obstacles change the whole flow',[
 'Raise voltage: the same blue characters jog faster and look more energetic.','Keep voltage fixed and raise resistance: watch the pit deepen, steps rise and planks become rougher.','Compare current and power. Open the gate to stop the entire flow; no electrons disappear.']),
'ohms-law':('Step 1 · Connect the ammeter: click the yellow meter, or drag its green plug to the green series socket.',slider('voltage','DC supply voltage',0,12,.5,6,'V')+slider('r1','Resistor R₁',20,100,5,20,'Ω')+'<label>Choose a circuit<select id="topology"><option value="single">One resistor · Ohm’s law</option><option value="series">Two resistors · series</option><option value="parallel">Two resistors · parallel</option></select></label>'+slider('r2','Resistor R₂',20,100,5,40,'Ω'),'Your instruments and I–V graph',[
 'Click the ammeter and voltmeter, or drag their coloured plugs to their matching sockets.','Turn on the DC button on the supply and close the actual switch in the circuit.','Change voltage and record at least three readings without changing the resistor. Compare the I–V graph.']),
'wire-resistance':('Keep the measuring current fixed. Change one wire factor and record the resistance.', '<label class="wide">Choose an investigation<select id="wire-investigation"><option value="length">Length · keep other factors fixed</option><option value="diameter">Diameter · keep other factors fixed</option><option value="temperature">Temperature · keep other factors fixed</option><option value="material">Material · compare equivalent wires</option></select></label><label id="material-control">Wire material<select id="material"><option value="copper">Copper</option><option value="nichrome">Nichrome</option><option value="iron">Iron</option></select></label>'+slider('length','Wire length',.5,5,.5,1,'m')+slider('diameter','Wire diameter',.2,1,.1,.4,'mm')+slider('temperature','Controlled temperature',0,100,5,20,'°C'),'Structure, resistance and a fair test',[
 'Choose a factor in the dropdown. Only that factor changes during this fair-test investigation.','Move the control or use its arrow keys. Watch the enlarged wire and meter readings together.','Record three different settings and compare the resistance graph. Change investigation to try another factor.'])}
for kind,(instruction,controls,side,steps) in configs.items():
 folder=DEST/'simulators';folder.mkdir(exist_ok=True)
 tabs='<nav class="example-tabs" aria-label="Electricity investigations">'+''.join(f'<a href="{k}.html"'+(' aria-current="page"' if k==kind else '')+f'>{name}</a>' for k,name in NAMES.items())+'</nav>'
 body=f'<section class="lab-title"><span class="kicker">Y9 ELECTRICITY · CIRCUITS INVESTIGATION</span><h1>{NAMES[kind]}</h1><p>{instruction}</p></section>{tabs}<section class="how-to"><h2>How to investigate</h2><ol>'+''.join(f'<li>{step}</li>' for step in steps)+'</ol></section>'+bench(kind,controls,instruction,side,True)+check()
 if kind=='pizza':body+='<section class="film-card"><div><span class="kicker">WATCH THE MODEL IN MOTION</span><h2>The Pizza Circuit · short film</h2><p>Follow pickup, delivery and the empty return. Compare more pizzas per courier with a harder road, while the same couriers circulate. This silent film has on-screen explanations.</p><a class="button" href="../media/pizza-circuit.mp4" download>Download the film · MP4</a></div><video controls preload="none" poster="../images/pizza-film-poster.webp" aria-label="Pizza Circuit: current, energy, voltage and resistance compared"><source src="../media/pizza-circuit.mp4" type="video/mp4"><track kind="captions" src="../media/pizza-circuit.vtt" srclang="en" label="English" default>Your browser can download the MP4 using the link beside this player.</video></section>'
 if kind=='resistance':body+='<section class="film-card"><div><span class="kicker">WATCH THE MODEL IN MOTION</span><h2>The Resistance Run · short film</h2><p>Compare a lower voltage, a higher voltage, and a much harder obstacle course. The same cast circulates in every scene. This silent cartoon has on-screen explanations.</p><a class="button" href="../media/resistance-run.mp4" download>Download the film · MP4</a></div><video controls preload="none" poster="../images/resistance-film-poster.webp" aria-label="Resistance Run: higher voltage and higher resistance compared"><source src="../media/resistance-run.mp4" type="video/mp4"><track kind="captions" src="../media/resistance-run.vtt" srclang="en" label="English" default>Your browser can download the MP4 using the link beside this player.</video></section>'
 if kind in ['pizza','resistance']:body+=f'<details class="original-reference sources"><summary>Your presentation illustration: inspect the original model</summary><img src="../images/{"pizza-circuit.png" if kind=="pizza" else "resistance-obstacles.png"}" alt="The unchanged illustration from your circuits presentation"><p>Both pictures have been adapted into separate animation layers. Pizza couriers and the blue Resistance Run characters move themselves; the original illustrations remain here for comparison.</p></details>'
 body+=sources+revision(4,'../circuits/revision.html','electric circuits')
 (folder/f'{kind}.html').write_text(shell(NAMES[kind],body,5,kind))

cpath=ROOT/'catalog.json';c=json.loads(cpath.read_text());subject=next(s for y in c['years'] if y['id']=='y9' for s in y['subjects'] if s['id']=='science')
activities=[dict(id='y9-electricity-lab',title='Electricity: charge and circuits',description='Two beginner-friendly lessons, guided static experiments and four separate circuit investigations.',href='activities/y9/science/electricity/',image='activities/y9/science/electricity/images/unit.svg',format='Interactive science unit',duration='Work at your pace')]
for key,title in [('static','Static electricity and charge'),('circuits','Electric circuits')]:
 for suffix,href,fmt,desc in [('',f'{key}/','Guided lesson','Read from the beginning and investigate the ideas with animated models.'),('-revision',f'{key}/revision.html','Revision simulator','60 explained questions with selectable areas and levels, practice and Test yourself.')]:activities.append(dict(id=f'y9-electricity-{key}{suffix}',title=title+(': revision simulator' if suffix else ''),description=desc,href=f'activities/y9/science/electricity/{href}',image=f'activities/y9/science/electricity/images/{"static" if key=="static" else "circuit"}.svg',format=(('Static charge revision' if key=='static' else 'Circuits revision') if suffix else ('Part 1 · Static electricity' if key=='static' else 'Part 2 · Circuits')),duration='Choose your session' if suffix else 'Work at your pace'))
for key,title in NAMES.items():activities.append(dict(id=f'y9-electricity-{key}',title=title,description=configs[key][0],href=f'activities/y9/science/electricity/simulators/{key}.html',image='activities/y9/science/electricity/images/'+('pizza-circuit.png' if key=='pizza' else 'resistance-obstacles.png' if key=='resistance' else 'circuit.svg'),format=title,duration='10–20 min'))
topic=dict(id='electricity',name='Electricity',appTitle='Electricity: charge and circuits',description='Explore static electricity and charge, then investigate current, voltage, resistance, circuits and power.',primaryActivity='y9-electricity-lab',activities=activities)
idx=next((i for i,t in enumerate(subject['topics']) if t['id']=='electricity'),None)
if idx is None:subject['topics'].append(topic)
else:subject['topics'][idx]=topic
cpath.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
print('Built Y9 Electricity: hub, two lessons, static experiments, four circuit simulations and two revision wrappers.')
